CARDS={}
def add(oid,p,a,g):CARDS.setdefault('OBJ-6117-'+oid,[]).append((p,a,g))
add('4.2-01','Calculate the theoretical MgO mass when 4.8 g Mg reacts completely with excess oxygen: 2Mg + O2 → 2MgO. Ar: Mg 24, O 16.','n(Mg)=4.8/24=0.200 mol. The Mg:MgO ratio is 1:1, so n(MgO)=0.200 mol. M(MgO)=40 g/mol; mass=0.200×40=8.00 g.',['0.200 mol Mg (1).','1:1 amount transfer to MgO (1).','8.00 g, accepting 8.0 g (1).'])
add('4.2-01','Calculate the magnesium mass required to produce 10.0 g MgO at complete conversion with excess oxygen: 2Mg + O2 → 2MgO. Ar: Mg 24, O 16.','M(MgO)=40 g/mol; n(MgO)=10.0/40=0.250 mol. n(Mg)=0.250 mol; mass=0.250×24=6.00 g.',['0.250 mol MgO (1).','1:1 ratio gives 0.250 mol Mg (1).','6.00 g Mg (1).'])
add('4.2-01','Calculate the CaO mass from complete decomposition of 25.0 g pure CaCO3: CaCO3 → CaO + CO2. Molar masses: CaCO3 100 g/mol, CaO 56 g/mol.','n(CaCO3)=25.0/100=0.250 mol. Ratio CaCO3:CaO=1:1, so mass(CaO)=0.250×56=14.0 g.',['0.250 mol CaCO3 (1).','1:1 amount transfer (1).','14.0 g CaO (1).'])
add('4.2-01','Calculate the water mass formed when 3.2 g O2 reacts completely with excess H2: 2H2 + O2 → 2H2O. Molar masses: O2 32 g/mol, H2O 18 g/mol.','n(O2)=3.2/32=0.100 mol. n(H2O)=2×0.100=0.200 mol; mass=0.200×18=3.60 g.',['0.100 mol O2 (1).','2:1 ratio gives 0.200 mol water (1).','3.60 g, accepting 3.6 g (1).'])
