 add('4.2-05',f'Calculate the molecular formula for empirical formula {empirical} and relative molecular mass {mr}. Ar: C 12, H 1, N 14, O 16.',f'Empirical formula mass={em}. Multiplier={mr}/{em}={multiple}. Multiply every subscript by {multiple}: {formula}.',[f'Empirical formula mass {em} (1).',f'Multiplier {multiple} (1).',f'{formula} (1); formula has no unit.'])
